reducedMotion:
@media (prefers-reduced-motion: reduce) {
  [data-enter-animation="fade-in"], [data-enter-animation="fade-in-stagger"] { opacity: 1; animation: auto ease 0s 1 normal none running none; }
}

@media (prefers-reduced-motion: reduce) {
  .palette-recommendations-loading-container { transition: none; }
  .palette-recommendations-placeholder { opacity: 1; animation: auto ease 0s 1 normal none running none; }
}

@media (prefers-reduced-motion: reduce) {
  .combobox-panel { animation: auto ease 0s 1 normal none running none; }
}

@media (prefers-reduced-motion: reduce) {
  .data-table-surface[data-pending="true"] tbody { transition: none; }
  .data-table-sort[data-pending="true"] .data-table-sort-caret { animation: auto ease 0s 1 normal none running none; }
}
